#!/bin/bash

# Removes the CA, certificates and keystore generated by setup.sh.
# Paths are resolved from this script's location, so running it from
# another directory never deletes files outside of config/.
set -euo pipefail

CONFIG_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
CA_DIR="${CONFIG_DIR}/ca"
CERTS_DIR="${CONFIG_DIR}/certs"

# Only the files generated by setup.sh: openssl-ca.cnf and san.cnf are kept
rm -f -- "${CA_DIR}"/*.pem "${CA_DIR}"/ca_database_index.txt* "${CA_DIR}"/ca_serial.txt*

if [ -d "${CERTS_DIR}" ]; then
    rm -r -- "${CERTS_DIR}"
fi
